import csv, os, re
fields = {'ssn': ['ssn','social_security'], 'payment_card': ['card_number','pan','credit_card'], 'account_credential': ['password','secret','credential'], 'bank_account': ['bank_account','iban','routing'], 'tax_id': ['tax_id','ein','tin']}
for root, dirs, files in os.walk('/app/models'):
    for f in files:
        if f.endswith('.py'):
            content = open(os.path.join(root,f)).read()
            for ftype, patterns in fields.items():
                for p in patterns:
                    if re.search(p, content, re.I) and not re.search('Encrypted|encrypted_type|CryptoField', content):
                        print(f'Potential unencrypted {ftype} in {f}')
"

